using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Collections.Generic;
public sealed class DofusOverlayOptions {public double opacity=1;public int portrait=80,dofus=66;public bool showPortrait=true,showDofus=true,showProgress=true,showNotes=true;}
public sealed class DofusSession {public string character="",guide="",step="",visited="";}
public sealed class DofusStepNote {public string key="",body="",custom="";public List<string> checkedItems=new List<string>();}
internal static class DofusTools {
 internal static void Validate(Data data){var d=data.dofus;if(d.overlay==null)d.overlay=new DofusOverlayOptions();var o=d.overlay;if(Double.IsNaN(o.opacity)||Double.IsInfinity(o.opacity)||o.opacity<.55||o.opacity>1||o.portrait<40||o.portrait>140||o.dofus<32||o.dofus>96)throw new InvalidDataException("Réglages de l’overlay invalides.");if(d.session==null)d.session=new DofusSession();var s=d.session;if((s.character??"").Length>100||!String.IsNullOrEmpty(s.guide)&&!TougliReader.ValidSlug(s.guide)||(s.step??"").Length>200||(s.visited??"").Length>50)throw new InvalidDataException("Session Dofus invalide.");if(d.stepNotes==null)d.stepNotes=new List<DofusStepNote>();if(d.stepNotes.Count>500||d.stepNotes.Any(n=>n==null||!Regex.IsMatch(n.key??"",@"^[a-f0-9]{64}$")||n.body==null||n.body.Length>4000||n.custom==null||n.custom.Length>2000||n.checkedItems==null||n.checkedItems.Count>200||n.checkedItems.Any(k=>!Regex.IsMatch(k??"",@"^[a-f0-9]{64}$")))||d.stepNotes.Select(n=>n.key).Distinct().Count()!=d.stepNotes.Count)throw new InvalidDataException("Notes Dofus invalides.");}
 internal static void SeedSession(Data data){var c=DofusCompanion.Character(data);if(c==null||!String.IsNullOrEmpty(data.dofus.session.character))return;var p=DofusCompanion.Find(data,c);data.dofus.session=new DofusSession{character=c.id,guide=c.guide,step=p==null?"":p.cursor};}
 internal static string Key(Data d,TougliStep step){var c=DofusCompanion.Character(d);return WorkspaceNext.Hash(Encoding.UTF8.GetBytes((c==null?"":c.id)+"/"+(c==null?"":c.guide)+"/"+step.Key));}
 internal static DofusStepNote Note(Data d,TougliStep step){if(step==null)return new DofusStepNote();string key=Key(d,step);var note=d.dofus.stepNotes.FirstOrDefault(n=>n.key==key);return note==null?new DofusStepNote{key=key}:new DofusStepNote{key=key,body=note.body,custom=note.custom,checkedItems=note.checkedItems.ToList()};}
 internal static void SaveNote(Store store,DofusStepNote note){PersonalWorkflows.Change(store,()=>{store.Value.dofus.stepNotes.RemoveAll(n=>n.key==note.key);if(!String.IsNullOrWhiteSpace(note.body)||!String.IsNullOrWhiteSpace(note.custom)||note.checkedItems.Count>0)store.Value.dofus.stepNotes.Add(note);});}
 internal static string ItemKey(string text){return WorkspaceNext.Hash(Encoding.UTF8.GetBytes(text));}
 internal static List<string> Prepare(TougliStep step,string custom){var items=new List<string>();if(step!=null){items.AddRange(step.Resources.Select(r=>r.Count+" × "+r.Name));items.AddRange((step.Details??"").Split('\n').Where(t=>t.TrimStart().StartsWith("Prérequis",StringComparison.OrdinalIgnoreCase)||Regex.IsMatch(t,@"\b[0-9][0-9 .]{0,30}\s*kamas\b",RegexOptions.IgnoreCase)).Select(t=>t.Trim()));}items.AddRange((custom??"").Split('\n').Select(s=>s.Trim()).Where(s=>s!=""));return items.Distinct().Take(200).ToList();}
 internal static void Remember(Store store){var c=DofusCompanion.Character(store.Value);if(c==null)return;var p=DofusCompanion.Find(store.Value,c);PersonalWorkflows.Change(store,()=>store.Value.dofus.session=new DofusSession{character=c.id,guide=c.guide,step=p==null?"":p.cursor,visited=DateTime.Now.ToString("o")});}
 internal static bool CanResume(Data data){return data.dofus.characters.Any(c=>c.id==data.dofus.session.character)&&TougliReader.ValidSlug(data.dofus.session.guide);}
 internal static void Resume(Store store){if(!CanResume(store.Value))throw new InvalidOperationException("Aucune session de personnage disponible.");PersonalWorkflows.Change(store,()=>{var s=store.Value.dofus.session;store.Value.dofus.active=s.character;var c=DofusCompanion.Character(store.Value);c.guide=s.guide;if(!String.IsNullOrEmpty(s.step))DofusCompanion.Get(store.Value,c).cursor=s.step;});}
 internal static void Test(string folder){var store=new Store(Path.Combine(folder,"dofus-tools"));var c=new DofusCharacter{id="tools",name="Test",guide="parcours-exemple"};store.Value.dofus.characters.Add(c);store.Value.dofus.active=c.id;var step=new TougliStep{Key="parcours-exemple/test",Details="Prérequis · quête test\nPrévoir 500 kamas.",Resources=new List<TougliResource>{new TougliResource{Name="Objet",Count=3}}};var note=Note(store.Value,step);note.body="À faire en guilde";note.custom="Acheter une potion";note.checkedItems.Add(ItemKey("3 × Objet"));SaveNote(store,note);Remember(store);var reopened=new Store(store.Root);if(Note(reopened.Value,step).body!=note.body||Prepare(step,note.custom).Count!=4||!CanResume(reopened.Value))throw new Exception("Notes, préparation ou reprise non conservées");reopened.Value.dofus.overlay.portrait=120;reopened.Value.dofus.overlay.opacity=.75;reopened.Save();if(new Store(store.Root).Value.dofus.overlay.portrait!=120)throw new Exception("Réglages overlay perdus");var other=new DofusCharacter{id="other",name="Autre",guide=c.guide};store.Value.dofus.characters.Add(other);store.Value.dofus.active=other.id;if(Note(store.Value,step).body!="")throw new Exception("Note partagée entre personnages");Resume(store);if(store.Value.dofus.active!=c.id)throw new Exception("Reprise du mauvais personnage");}
}
